int YUY_Draw_Piont(unsigned char * YuvBuf, int ImgW, int ImgH, int fmt,int PntX, int PntY, int Color)
{
   int ret = -1;

   if(YuvBuf == NULL)
       return ret;

    fmt =12;
   switch(fmt)
   {
       case 12://V4L2_PIX_FMT_NV12:
       {
           int Yoffset = PntY * ImgW + PntX;
           int Uoffset,Voffset;

           Uoffset =  ImgH * ImgW + (PntY / 2) * ImgW + PntX / 2 * 2 ;
           Voffset =  Uoffset + 1;

           YuvBuf[Yoffset] = s_color_table[Color].Y;
           YuvBuf[Uoffset] = s_color_table[Color].U;
           YuvBuf[Voffset] = s_color_table[Color].V;
       }
           ret = 0;
       break;

       default:
           ret = -2;
       break;
   }
   return ret;
}

int YUY_Draw_Line(unsigned char * YuvBuf, int ImgW, int ImgH, int fmt,int SPntX, int SPntY,int EPntX, int EPntY, int Color,int lineWidth)
{
   int ret = -1;
   if(YuvBuf == NULL)
       return ret;

   if(lineWidth == 0)
       lineWidth = 1;

 //  printf("SPntX=%d,EPntX=%d,SPntY=%d,EPntY=%d\n", SPntX, EPntX, SPntY, EPntY);

   SPntX = (SPntX + lineWidth >= ImgW) ? (ImgW - lineWidth) : (SPntX < 0 ? 0 : SPntX);
   EPntX = (EPntX + lineWidth >= ImgW) ? (ImgW - lineWidth) : (EPntX < 0 ? 0 : EPntX);
   SPntY = (SPntY + lineWidth >= ImgH) ? (ImgH - lineWidth) : (SPntY < 0 ? 0 : SPntY);
   EPntY = (EPntY + lineWidth >= ImgH) ? (ImgH - lineWidth) : (EPntY < 0 ? 0 : EPntY);

   int dx = (SPntX > EPntX) ? (SPntX - EPntX) : (EPntX - SPntX);
   int dy = (SPntY > EPntY) ? (SPntY - EPntY) : (EPntY - SPntY);
   int xstep = (SPntX < EPntX) ? 1 : -1;
   int ystep = (SPntY < EPntY) ? 1 : -1;
   int nstep = 0, eps = 0;
   int pointX = SPntX;
   int pointY = SPntY;
  // printf("dx=%d,dy=%d,xstep=%d,ystep=%d,pointX=%d,pointY=%d\n",
  //         dx, dy, xstep, ystep, pointX, pointY);

    if(dx > dy)
   {
       while(nstep <= dx)
       {
           ret = YUY_Draw_Piont(YuvBuf, ImgW, ImgH, fmt, pointX, pointY, Color);
           if(ret < 0)
               break;

           eps += dy;
           if( (eps << 1) >= dx )
           {
               pointY += ystep;
               eps -= dx;
           }
           pointX += xstep;
           nstep++;
       }
   }
   else
   {
       while(nstep <= dy)
       {
           ret = YUY_Draw_Piont(YuvBuf, ImgW, ImgH, fmt, pointX, pointY, Color);
           if(ret < 0)
               break;

           eps += dx;
           if( (eps << 1) >= dy )
           {
               pointX += xstep;
               eps -= dy;
           }
               pointY += ystep;
               nstep++;
       }
   }
   return ret;
}

int YUY_Draw_num(unsigned char * YuvBuf, int ImgW, int ImgH, int fmt,int SPX, int SPY, int id, int Color)
{
   int ret = -1;
   int SPntX = 0;
   int SPntY = 0;
   unsigned char bitmap_bytes[4*32];
   if(YuvBuf == NULL)
       return ret;
   switch (id)
	{
	   case 0: memcpy(bitmap_bytes,bitmap_bytes_0,sizeof(bitmap_bytes_0));break;
	   case 1: memcpy(bitmap_bytes,bitmap_bytes_1,sizeof(bitmap_bytes_1));break;
	   case 2: memcpy(bitmap_bytes,bitmap_bytes_2,sizeof(bitmap_bytes_2));break;
	   case 3: memcpy(bitmap_bytes,bitmap_bytes_3,sizeof(bitmap_bytes_3));break;
	   case 4: memcpy(bitmap_bytes,bitmap_bytes_4,sizeof(bitmap_bytes_4));break;
	   case 5: memcpy(bitmap_bytes,bitmap_bytes_5,sizeof(bitmap_bytes_5));break;
	   case 6: memcpy(bitmap_bytes,bitmap_bytes_6,sizeof(bitmap_bytes_6));break;
	   case 7: memcpy(bitmap_bytes,bitmap_bytes_7,sizeof(bitmap_bytes_7));break;
	   case 8: memcpy(bitmap_bytes,bitmap_bytes_8,sizeof(bitmap_bytes_8));break;
	   case 9: memcpy(bitmap_bytes,bitmap_bytes_9,sizeof(bitmap_bytes_9));break;
	   default: break;
	 }
   for(int i = 0; i<4*32; i++)
   {
		for(int j = 0; j<8; j++)
		{
			if((bitmap_bytes[i]<<j)&0x80)
			{
				SPntY = (i/4)+1 + SPY;
				SPntX = (i%4)*8+j + SPX;
				YUY_Draw_Piont(YuvBuf, ImgW, ImgH, fmt, SPntX, SPntY, Color);
				//printf("x:%d,y:%d\n",SPntX,SPntY);
			}
			//SPntX++;		
		}
   }
   
   return ret;
}

